import {COMMONS,commonsKey} from './commons.js?v=32.0.0';
const directions=['↑','→','↓','←'];
export function commonsActivity(s,kind,tiles,{E,esc}){
 const a=COMMONS[kind],note=s.commonsNotes.find(n=>commonsKey(n.mallId,n.floor,n.kind)===commonsKey(s.mallId,s.floor||0,kind)),done=note?.day===s.day;
 return `<div class="modal-body commons-activity"><p>${esc(a.description)}</p>${kind==='mosaic'?`<div class="mosaic-pattern"><strong>Match this route: ↑ → ↓</strong><div role="group" aria-label="Mosaic tiles">${tiles.map((turn,i)=>`<button data-action="commons-turn" data-id="${i}" aria-label="Turn tile ${i+1}, currently ${['up','right','down','left'][turn]}"><span aria-hidden="true">${directions[turn]}</span><small>Turn tile ${i+1}</small></button>`).join('')}</div><p role="status">${tiles.every((t,i)=>t===E.MOSAIC_TARGET[i])?'The route lines up. Save your discovery.':'Turn each tile clockwise until the three arrows match.'}</p></div><button class="button orange wide" data-action="commons-save" data-id="mosaic" ${done||!tiles.every((t,i)=>t===E.MOSAIC_TARGET[i])?'disabled':''}>Save the mosaic discovery</button>`:`<div class="commons-pages">${a.choices.map(c=>`<article><h3>${esc(c.name)}</h3><p>${esc(c.text)}</p><button class="button secondary" data-action="commons-save" data-id="${kind}" data-choice="${c.id}" ${done?'disabled':''}>${kind==='reading'?'Remember this story':'Sketch this detail'}</button></article>`).join('')}</div>`}<p class="hint">${done?'Discovery saved here today. Read and explore freely; return tomorrow for another note.':`Free · ${a.minutes} game minutes · +${a.recovery} stamina. First discovery here: 5 XP. Find all three kinds in this mall for 25 extra XP.`}</p><div class="service-links"><button class="button secondary" data-action="commons-notebook">My discovery notebook</button><button class="text-button" data-action="close">Back to the mall</button></div></div>`;
}
export function commonsNotebook(s,{E,esc}){
 const status=E.commonsStatus(s),notes=s.commonsNotes.filter(n=>n.mallId===s.mallId);
 return `<div class="modal-body"><p>Discover the mosaic table, reading shelf and garden study. Each mall has its own three-stop trail.</p><p class="hint">${status.count}/3 kinds discovered at ${esc(E.mallOf(s).name)}${status.complete?' · Trail complete ✓':''}</p><div class="commons-pages">${Object.entries(COMMONS).map(([kind,a])=>{const found=notes.filter(n=>n.kind===kind);return `<article><h3>${a.icon} ${a.name} ${found.length?'✓':''}</h3>${found.map(n=>`<p><small>Day ${n.day} · ${esc(E.planFor(s).levels[n.floor])}</small><br>${esc(kind==='mosaic'?'A little route, pieced together.':a.choices.find(c=>c.id===n.choice).name)}</p>`).join('')||'<p>Still to discover. Open the map to walk to this stop.</p>'}</article>`;}).join('')}</div><button class="button orange wide" data-action="center-map">Find the public stops on the map</button></div>`;
}
export function publicStops(layout,floor,{E,esc,s}){
 const fixtures=layout.environment.fixtures.filter(f=>f.approach),commons=fixtures.filter(f=>f.activity),rest=fixtures.filter(f=>f.kind==='bench'),others=fixtures.filter(f=>!f.activity&&f.kind!=='bench');
 const row=(id,type,name,detail)=>`<button class="public-stop" data-action="center-stop" data-id="${id}" data-type="${type}" data-floor="${floor}"><span><strong>${esc(name)}</strong><small>${esc(detail)}</small></span><b aria-hidden="true">↗</b></button>`;
 return `<section class="map-public-stops"><h3>Things to do on this floor</h3><div class="public-stop-grid">${commons.map(f=>row(f.id,'fixture',COMMONS[f.activity].name,COMMONS[f.activity].verb+' · free')).join('')}${layout.venues.map(v=>row(v.id,'venue',({rest:'Rest lounge',services:'Guest services',food:'Food court',coffee:'Coffee stop',photo:'Photo studio',bridge:'Garden walk',popup:'Pop-up pavilion',flowers:'Flower studio',cinema:'Cinema',carousel:'Carousel',art:'Art walk',lounge:'Quiet lounge'})[v.id]||v.id,'Walk here & explore')).join('')}</div><details><summary>Benches, kiosks & directories · ${rest.length+others.length}</summary><div class="public-stop-grid">${[...rest,...others].map((f,i)=>row(f.id,'fixture',f.kind==='bench'?'Bench '+(i+1):f.kind==='directory'?'Directory':({coffee:'Coffee kiosk',photo:'Photo spot',flowers:'Flower cart',popup:'Pop-up counter'})[f.venue]||f.kind,'Near '+(layout.campus.nodes.find(n=>n.id===f.node)?.label||'the concourse'))).join('')}</div></details><button class="button secondary" data-action="commons-notebook">My discoveries · ${E.commonsStatus(s).count}/3</button></section>`;
}
